<file path="src/invoices.js">
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} params
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate issueDate format and value
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate quantity is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for one line: quantity times unit price.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate invoice totals: subtotal and total (discounts and VAT calculated separately).
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {object} invoice
 * @param {{ sku: string, qty: number }} params
 */
export function addLine(invoice, { sku, qty }) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    // Increase qty on existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {object} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice: assign a number and change status to 'issued'.
 * @param {object} invoice
 * @param {Array<string>} existingNumbers
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return fail(numberResult.error);

  return ok({
    ...invoice,
    number: numberResult.value,
    status: 'issued',
  });
}

function isValidDate(dateStr) {
  // Check format YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;

  // Parse and validate
  const date = new Date(dateStr + 'T00:00:00Z');
  const [year, month, day] = dateStr.split('-').map(Number);

  return date.getUTCFullYear() === year &&
         date.getUTCMonth() + 1 === month &&
         date.getUTCDate() === day;
}
</file>

<file path="src/money.js">
import { ok, fail } from './result.js';

/**
 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
 * @param {number} x
 * @returns {number}
 */
export function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
 * @param {string} text
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}
</file>

<file path="src/numbering.js">
import { ok, fail } from './result.js';

/**
 * Calculate the next invoice number for a given issue date.
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  // Extract year from issueDate
  const yearMatch = /^(\d{4})-/.exec(issueDate);
  if (!yearMatch) return fail('DATE_INVALID');
  const year = yearMatch[1];

  // Filter numbers for this year and extract counters
  const prefix = `INV-${year}-`;
  const counters = existingNumbers
    .filter(num => num.startsWith(prefix))
    .map(num => {
      const counter = num.slice(prefix.length);
      return parseInt(counter, 10);
    })
    .filter(counter => !isNaN(counter));

  // Find max counter, or start at 0
  const maxCounter = counters.length > 0 ? Math.max(...counters) : 0;
  const nextCounter = maxCounter + 1;

  // Format with 4 digits, zero-padded
  const numberString = `${prefix}${String(nextCounter).padStart(4, '0')}`;
  return ok(numberString);
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';
import { fail } from './result.js';

/**
 * Render an invoice as plain text.
 * @param {object} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  // Get customer info
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  const customer = customerResult.value;
  const totals = invoiceTotals(invoice);

  // Build the invoice text
  const lines = [];

  // First line: invoice number or DRAFT
  const numberLine = invoice.number || 'DRAFT';
  lines.push(numberLine);

  // Second line: customer name
  lines.push(customer.name);

  // Blank line
  lines.push('');

  // Line items
  for (const line of invoice.lines) {
    const total = line.qty * line.unitPrice;
    const itemLine = `${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(total)}`;
    lines.push(itemLine);
  }

  // Blank line
  lines.push('');

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return { ok: true, value: lines.join('\n') };
}
</file>

<file path="src/result.js">
/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}
</file>

